uce Chicken Spaghetti Half","s":"01623","b":null,"c":"Chicken","u":"pcs","o":{"musammaa-cafe":{"p":35.0,"q":999,"a":true,"st":"kitchen"}}},{"n":"Woven Fabric Bags (W cut/size.11in x 14in) - SMALL","s":"01594","b":null,"c":"Inventory","u":"pcs","o":{"musammaa-cafe":{"p":0.0,"q":14,"a":false,"st":null}}},{"n":"XL 150ml","s":"01207","b":null,"c":"Soft Drinks","u":"pcs","o":{"musammaa-cafe":{"p":25.0,"q":1,"a":true,"st":null}}},{"n":"XL 250ml","s":"02049","b":null,"c":"Soft Drinks","u":"pcs","o":{"musammaa-cafe":{"p":35.0,"q":0,"a":true,"st":null}}},{"n":"XL ENERGY DRINK 250ML","s":"01723","b":"5906485301012","c":"Energy & Soft Drinks","u":"pcs","o":{"musammaa-cafe":{"p":30.0,"q":3,"a":true,"st":null},"maaloodhu-cafe":{"p":45.0,"q":0,"a":true,"st":null}}},{"n":"Yellow Banana","s":"01756","b":"123033","c":"Fresh Produce","u":"pcs","o":{"musammaa-cafe":{"p":10.0,"q":0,"a":true,"st":null}}},{"n":"Yellow Dhal","s":"02124","b":null,"c":"Inventory","u":"kg","o":{"musammaa-cafe":{"p":0.0,"q":5,"a":false,"st":null}}},{"n":"YEYE COFFEE MIX 3in1 20g","s":"01206","b":null,"c":"Inventory","u":"pcs","o":{"musammaa-cafe":{"p":10.0,"q":76,"a":false,"st":null}}},{"n":"Zero Coke 330ml","s":"01872","b":"9501101331501","c":"Soft Drinks","u":"pcs","o":{"musammaa-cafe":{"p":15.0,"q":0,"a":true,"st":null}}},{"n":"Zfold towel 23x23cm (tissue)","s":"02118","b":null,"c":"Inventory","u":"pcs","o":{"musammaa-cafe":{"p":0.0,"q":9,"a":false,"st":null}}}]$j$::jsonb) loop
    -- category
    v_slug := trim(both '-' from regexp_replace(lower(r ->> 'c'), '[^a-z0-9]+', '-', 'g'));
    insert into public.categories (name, slug) values (r ->> 'c', v_slug)
    on conflict (slug) do nothing;
    select id into v_cat from public.categories where slug = v_slug;

    -- find the variant: by code, else by exact name of an item you added by hand (single variant, no code yet)
    select pv.id, pv.product_id into v_variant, v_product from public.product_variants pv where pv.sku = r ->> 's';
    if v_variant is null then
      select p.id into v_product from public.products p
       where lower(p.name) = lower(r ->> 'n')
         and (select count(*) from public.product_variants x where x.product_id = p.id) = 1
         and exists (select 1 from public.product_variants x where x.product_id = p.id and x.sku is null)
       limit 1;
      if v_product is not null then
        select id into v_variant from public.product_variants where product_id = v_product;
        update public.product_variants set sku = r ->> 's' where id = v_variant and sku is null;
      end if;
    end if;

    select coalesce(max((x.value ->> 'p')::numeric), 0) into v_price
      from jsonb_each(r -> 'o') x where (x.value ->> 'a')::boolean;
    if v_price = 0 then
      select coalesce(max((x.value ->> 'p')::numeric), 0) into v_price from jsonb_each(r -> 'o') x;
    end if;
    select bool_or((x.value ->> 'a')::boolean) into v_any from jsonb_each(r -> 'o') x;

    if v_variant is null then
      v_slug := trim(both '-' from regexp_replace(lower(left(r ->> 'n', 70)), '[^a-z0-9]+', '-', 'g'));
      if v_slug = '' then v_slug := 'item'; end if;
      v_slug := v_slug || '-' || (r ->> 's');
      insert into public.products (name, slug, category_id, unit, is_active)
      values (left(r ->> 'n', 160), v_slug, v_cat, r ->> 'u', coalesce(v_any, false))
      on conflict (slug) do update set category_id = excluded.category_id
      returning id into v_product;
      insert into public.product_variants (product_id, sku, price, stock, is_active)
      values (v_product, r ->> 's', v_price, 0, true)
      returning id into v_variant;
      n_new := n_new + 1;
    else
      update public.products
         set category_id = coalesce(category_id, v_cat),
             unit = coalesce(unit, r ->> 'u'),
             is_active = is_active or coalesce(v_any, false)
       where id = v_product;
      n_found := n_found + 1;
    end if;

    -- barcode (only if nobody else has it)
    if r ->> 'b' is not null then
      update public.product_variants set barcode = r ->> 'b'
       where id = v_variant and barcode is null
         and not exists (select 1 from public.product_variants z where z.barcode = r ->> 'b' and z.id <> v_variant);
    end if;

    -- per outlet: price, stock, on/off, screen
    for o in select key, value from jsonb_each(r -> 'o') loop
      insert into public.outlet_variants (outlet_id, variant_id, price, stock, is_active, station)
      values (
        (v_outlets ->> o.key)::uuid, v_variant,
        (o.value ->> 'p')::numeric, (o.value ->> 'q')::int, (o.value ->> 'a')::boolean,
        nullif(o.value ->> 'st', 'null')
      )
      on conflict (outlet_id, variant_id) do update
        set price = excluded.price, stock = excluded.stock, is_active = excluded.is_active, station = excluded.station;
      n_rows := n_rows + 1;
    end loop;
  end loop;
  raise notice 'Imported: % new items, % matched existing items, % outlet rows.', n_new, n_found, n_rows;
end
$import$;
